SELECT g.id, g.grht, g.glft, g.group_name, g.parent_id, g.group_level, g.group_type
FROM sys_tenant_group AS g





             g.glft >= #{item.left, jdbcType=INTEGER} AND g.grht <= #{item.rght, jdbcType=INTEGER}       



		AND 1 = 0


	AND tenant_id = #{tenantId, jdbcType=VARCHAR}

SELECT g.id, g.grht, g.glft, g.group_name, g.parent_id, g.group_level
FROM sys_tenant_user_group as ug
left join sys_tenant_group AS g
on ug.group_id = g.id
where ug.user_id = #{uid, jdbcType=VARCHAR}
and g.tenant_id = #{tenantId, jdbcType=VARCHAR}
